parameters.text:
=You are helping craft a personalized, warm outreach message for a parent satisfaction survey. 

Create a friendly, professional introduction message that:
- Feels personal and specific to this family
- Mentions their child by name naturally
- References their school experience contextually
- Invites them to participate in feedback without being pushy
- Keeps it conversational and warm

Context:
- Parent: {{ $json.parent.name }}
- Child: {{ $json.schoolContext.childName }}
- Grade: {{ $json.schoolContext.gradeLevel }}
- Teacher: {{ $json.schoolContext.teacherName }}
- School: {{ $json.schoolContext.schoolName }}
- Survey goal: {{ $json.surveyGoal.goal }}

Generate ONLY the personalized introduction message (2-3 sentences max). Do not include buttons or calls to action - just the warm, personal greeting.

parameters.jsCode:
// Mock LLM response for personalized intro in Mexican Spanish
const data = $input.first().json;

// Simulate what an LLM would generate for a warm, personalized intro
const mockResponses = [
  `¡Hola ${data.parent.name}! Esperamos que ${data.schoolContext.childName} esté disfrutando mucho el ${data.schoolContext.gradeLevel} con ${data.schoolContext.teacherName}. Nos encantaría conocer su experiencia familiar en ${data.schoolContext.schoolName}.`,

  `¡Buenas tardes ${data.parent.name}! Sabemos que ${data.schoolContext.childName} ha estado participando activamente en ${data.schoolContext.gradeLevel}. Nos gustaría saber cómo se sienten con el progreso en ${data.schoolContext.schoolName}.`,

  `Estimada ${data.parent.name}, esperamos que ${data.schoolContext.childName} esté teniendo una excelente experiencia en ${data.schoolContext.gradeLevel} con ${data.schoolContext.teacherName}. Su opinión sobre ${data.schoolContext.schoolName} es muy valiosa para nosotros.`
];

// Select a response (in real implementation, this would be LLM-generated)
const selectedResponse = mockResponses[0]; // Using first one for consistency

// Simulate LLM processing time
const processingDelay = Math.random() * 500 + 200; // 200-700ms delay

return [{
  json: {
    text: selectedResponse,
    mockProcessingTime: processingDelay,
    language: "es-MX",
    generatedAt: new Date().toISOString()
  }
}];

// Simulate the JSON payload for parent satisfaction survey
const mockPayload = {
  "conversation_target": {
    "phone_number": "+1234567890",
    "user_id": "parent_123", 
    "name": "Ignacio Rosales"
  },
  "conversation_config": {
    "goal": "collect_parent_satisfaction_feedback",
    "prompt": "Converse con los padres para comprender su satisfacción general con la experiencia escolar de su hijo. Analice aspectos como el nivel académico, la comunicación, las instalaciones, las actividades extracurriculares y cualquier inquietud o sugerencia de mejora.",
    "max_turns": 10,
    "timeout_hours": 48,
    "conversation_id": "parent_survey_" + Date.now()
  },
  "context": {
    "school_name": "Colegio La Salle",
    "child_name": "Janeth Rosales",
    "grade_level": "5to",
    "enrollment_year": "2022",
    "teacher_name": "Ms. Rodriguez",
    "survey_type": "quarterly_satisfaction"
  },
  "callback_config": {
    "webhook_url": "https://cerebrolabs.ai/api/v1/parent-feedback",
    "auth_token": "school_bearer_token_here"
  }
};

return [{ json: mockPayload }];

// Extract the key information from the parent survey payload
const payload = $input.first().json;

// Extract parent information
const parent = {
  phone: payload.conversation_target.phone_number,
  userId: payload.conversation_target.user_id,
  name: payload.conversation_target.name
};

// Extract survey goal and configuration
const surveyGoal = {
  goal: payload.conversation_config.goal,
  prompt: payload.conversation_config.prompt,
  maxTurns: payload.conversation_config.max_turns,
  conversationId: payload.conversation_config.conversation_id,
  surveyType: payload.context.survey_type
};

// Extract school and child context for personalization
const schoolContext = {
  schoolName: payload.context.school_name,
  childName: payload.context.child_name,
  gradeLevel: payload.context.grade_level,
  teacherName: payload.context.teacher_name,
  enrollmentYear: payload.context.enrollment_year
};

// Return structured data for LLM processing
return [{
  json: {
    parent: parent,
    surveyGoal: surveyGoal,
    schoolContext: schoolContext,
    originalPayload: payload // Keep original for reference
  }
}];

// Combine the mock LLM-generated intro with our structured data
const originalData = $('Extract key information').first().json;
const generatedIntro = $input.first().json.text; // The mock LLM output

return [{
  json: {
    ...originalData, // Spread all the original extracted data
    personalizedIntro: generatedIntro, // Add the mock LLM-generated intro
    language: "es-MX",
    generatedAt: new Date().toISOString()
  }
}];

// Simulate what the WhatsApp template message would look like in Spanish
const data = $input.first().json;

// Use the mock LLM-generated intro in Spanish
const templateMessage = {
  to: data.parent.phone,
  type: "template",
  template: {
    name: "encuesta_satisfaccion_padres", // Spanish template name
    language: { code: "es_MX" },
    components: [
      {
        type: "body", 
        parameters: [
          { type: "text", text: data.personalizedIntro },
          { type: "text", text: "3-4 minutos" } // Survey duration in Spanish
        ]
      }
    ]
  }
};

// What the parent would actually see in Spanish:
const actualMessage = `${data.personalizedIntro}

Esta breve encuesta toma solo 3-4 minutos y nos ayuda a mejorar nuestra comunidad escolar.

¿Le gustaría compartir su experiencia?

[Comenzar Encuesta] [Tal vez después]`;

return [{
  json: {
    whatsappTemplate: templateMessage,
    messagePreview: actualMessage,
    status: "template_would_be_sent",
    language: "es-MX",
    timestamp: new Date().toISOString()
  }
}];
